-- 0145_permissions_seed_actions.sql
-- Why: Seeds the action catalog (every <app>.<resource>.<verb> permission
--   identifier in the platform). Generated from
--   docs/permissions-action-manifest.json by
--   scripts/build-permission-codegen.mjs. Re-running the codegen and
--   committing the diff is the supported way to add or remove
--   permissions; CI guard scripts/check-permission-catalog.mjs catches
--   drift on every push.
-- Client impact: additive only. Inserts ~1056 permissions; uses ON
--   CONFLICT (id) DO UPDATE so re-running the migration on a partially-
--   seeded DB picks up new metadata without violating the body-checksum
--   rule (this file is rewritten only by the codegen, then never
--   touched once applied).

-- ──────────────────────────────────────────────────────────────────────
-- Catalog seed (1056 rows)
-- ──────────────────────────────────────────────────────────────────────

ON CONFLICT (id) DO UPDATE SET
    app = EXCLUDED.app,
    resource = EXCLUDED.resource,
    verb = EXCLUDED.verb,
    description = EXCLUDED.description,
    is_destructive = EXCLUDED.is_destructive,
    requires_confirmation = EXCLUDED.requires_confirmation,
    is_read = EXCLUDED.is_read;
